    Implements a backtracking regex matching algorithm that supports literal characters,
    '.', '*', and '+' operators.
    """
    def is_match(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern) and t_index == len(text):
            return True
        if p_index < len(pattern) and t_index == len(text):
            # Handle remaining pattern with '*' or '+' at the end
            return all(c in '*+' for c in pattern[p_index:])

